using System;using System.IO;using System.Drawing;using System.Diagnostics;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Linq;
[assembly:AssemblyInformationalVersion("0.3.0-preview.22")]
public static class Storage{public static string PathName="unused";}
internal sealed class BootstrapWindow:Form {
 readonly CancellationTokenSource cancel=new CancellationTokenSource();readonly Label status=new Label();readonly ProgressBar progress=new ProgressBar();readonly string[] args;bool finished;
 internal BootstrapWindow(string[] arguments){args=arguments;Text="AsterHub 更新";ClientSize=new Size(460,172);AutoScaleMode=AutoScaleMode.Dpi;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(28,31,38);ForeColor=Color.FromArgb(232,236,243);Font=new Font("Segoe UI",11);var title=new Label{Text="正在准备 AsterHub 更新",AutoSize=true,Location=new Point(28,24)};status.Text="正在连接下载服务…";status.SetBounds(28,65,404,30);progress.SetBounds(28,110,404,14);Controls.AddRange(new Control[]{title,status,progress});Shown+=async(s,e)=>await Run();FormClosing+=(s,e)=>{if(!finished)cancel.Cancel();};}
 async Task Run(){try{string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AsterHub","PreviewUpdates","FullPayload");
#if BOOTSTRAP_QA
 var custom=args.FirstOrDefault(a=>a.StartsWith("/AQBOOTSTRAPCACHE=",StringComparison.OrdinalIgnoreCase));if(custom!=null)folder=custom.Substring(custom.IndexOf('=')+1);
#endif
 var values=args.Where(a=>!a.StartsWith("/AQBOOTSTRAPCACHE=",StringComparison.OrdinalIgnoreCase)).ToArray();
 while(true){try{var report=new Progress<double>(p=>{if(IsDisposed)return;progress.Value=Math.Max(0,Math.Min(100,(int)p));status.Text="正在下载更新  "+Math.Round(p)+"%";});string installer=await BootstrapCore.Download(folder,report,cancel.Token);cancel.Token.ThrowIfCancellationRequested();status.Text="正在安装更新…";var start=new ProcessStartInfo(installer,BootstrapCore.JoinArguments(values)){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(installer)};var process=Process.Start(start);if(process==null)throw new IOException("无法启动安装程序。");Hide();await Task.Run(()=>process.WaitForExit());Environment.ExitCode=process.ExitCode;break;}catch(OperationCanceledException){Environment.ExitCode=2;break;}catch(Exception ex){if(cancel.IsCancellationRequested){Environment.ExitCode=2;break;}bool recoverable=UpdateDownload.IsRecoverable(ex);string message=recoverable?"下载暂时中断，已完成的部分会保留。是否继续下载？":AppUpdates.FriendlyError(ex);if(!recoverable||MessageBox.Show(this,message,"AsterHub 更新",MessageBoxButtons.RetryCancel,MessageBoxIcon.Information)!=DialogResult.Retry){if(!recoverable)MessageBox.Show(this,message,"AsterHub 更新",MessageBoxButtons.OK,MessageBoxIcon.Warning);Environment.ExitCode=1;break;}}}
 }catch(Exception ex){Environment.ExitCode=1;if(!IsDisposed)MessageBox.Show(this,ex.Message,"AsterHub 更新",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{finished=true;Close();}}
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new BootstrapWindow(args));}
}
